// === Tab: mySketch ===
// LUX SYNESTHESIA ∞ | v2: Experiencia audiovisual expandida

let activeNotes = {};
let fft, reverb;
let kickOsc, kickEnv;
let lastBeat = 0;
let beatInterval = 500;

let currentScale = [];
let scaleColor = [255, 255, 255];

let scales = {
  'A': [261.63, 293.66, 329.63, 349.23, 392.00, 440.00, 493.88],
  'S': [261.63, 293.66, 311.13, 349.23, 392.00, 415.30, 466.16],
  'D': [261.63, 293.66, 329.63, 392.00, 440.00],
  'F': [261.63, 277.18, 311.13, 349.23, 392.00, 466.16, 523.25]
};

let scaleThemes = {
  'A': [240, 240, 255],
  'S': [255, 200, 220],
  'D': [200, 255, 180],
  'F': [160, 220, 255]
};

let sculptures = [];

function setup() {
  createCanvas(windowWidth, windowHeight, WEBGL);
  fft = new p5.FFT();
  reverb = new p5.Reverb();

  kickOsc = new p5.Oscillator('sine');
  kickEnv = new p5.Envelope();
  kickEnv.setADSR(0.001, 0.1, 0.2, 0.2);
  kickEnv.setRange(1.2, 0);
  kickOsc.amp(kickEnv);
  kickOsc.start();
  reverb.process(kickOsc, 4, 3);

  currentScale = scales['A'];
  scaleColor = scaleThemes['A'];
  noCursor();
  colorMode(HSB, 360, 100, 100, 255);
}

function draw() {
  background(0);
  orbitControl(0.8, 0.8, 0.1);

  // BEAT
  beatInterval = map((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), -width / 2, width / 2, 1400, 100);
  if (millis() - lastBeat > beatInterval) {
    playKick();
    lastBeat = millis();
  }

  let pulse = map(sin(millis() / beatInterval * PI), -1, 1, 40, 160);
  let hueColor = map(pulse, 40, 160, 180, 360);
  pointLight(hueColor, 80, 100, 0, 0, 400);
  ambientLight(20);
  noStroke();
  fill(hueColor, 80, 100, 100);
  sphere(pulse, 48, 48);

  // AUDIO REACTIVO 3D FIELD
  let spectrum = fft.analyze();
  for (let i = 0; i < spectrum.length; i += 20) {
    let angle = map(i, 0, spectrum.length, 0, TWO_PI);
    let radius = map(spectrum[i], 0, 255, 50, 600);
    push();
    rotateY(frameCount * 0.002 + angle);
    rotateX(frameCount * 0.001);
    translate(cos(angle) * radius, sin(angle * 2) * radius / 2, sin(angle) * radius);
    let col = map(i, 0, spectrum.length, 180, 360);
    fill(col, 80, 100, 90);
    sphere(6 + sin(frameCount * 0.01 + i) * 3, 8, 6);
    pop();
  }

  // ESCULTURAS DINÁMICAS
  for (let s of sculptures) {
    s.update();
    s.display();
  }
  sculptures = sculptures.filter(s => s.life > 0);
}

function playKick() {
  kickOsc.freq(50);
  kickEnv.play();
}

function keyPressed() {
  getAudioContext().resume();
  let k = key.toUpperCase();
  if (scales[k]) {
    currentScale = scales[k];
    scaleColor = scaleThemes[k];
    return;
  }

  if (k >= '1' && k <= '7') {
    let i = int(k) - 1;
    if (currentScale[i] && !activeNotes[k]) {
      let freq = currentScale[i];
      let osc = new p5.Oscillator('sawtooth');
      let env = new p5.Envelope();
      env.setADSR(0.05, 0.2, 0.6, 0.5);
      env.setRange(0.5, 0);
      osc.amp(env);
      osc.freq(freq);
      osc.start();
      env.play();
      reverb.process(osc, 6, 3);
      activeNotes[k] = { osc, env };
      sculptures.push(new Sculpture(freq));
    }
  }
}

function keyReleased() {
  var k = key.toUpperCase();
  if (activeNotes[k]) {
    let { osc, env } = activeNotes[k];
    env.triggerRelease();
    setTimeout(() => osc.stop(), 600);
    delete activeNotes[k];
  }
}

class Sculpture {
  constructor(freq) {
    this.pos = createVector(0, 0, 0);
    this.vel = p5.Vector.random3D().mult(random(3, 6));
    this.size = map(freq, 200, 800, 20, 50);
    this.life = 255;
    this.hue = map(freq, 200, 800, 180, 360);
    this.rot = random(TWO_PI);
  }

  update() {
    this.pos.add(this.vel);
    this.life -= 2;
  }

  display() {
    push();
    translate(this.pos);
    rotateY(this.rot + frameCount * 0.01);
    fill(this.hue, 80, 100, this.life);
    box(this.size * (this.life / 255));
    pop();
  }
}

